def _safe_int(value):
    if value is None:
        return None
    try:
        if isinstance(value, str):
            value = value.strip().replace(",", "")
        return int(value)
    except Exception:
        return None

def _text(coin, attrs=None):
    if attrs is None:
        attrs = [
            "name", "country", "denomination", "mint", "location", "notes",
            "material", "ruler", "issuer", "region", "type"
        ]
    parts = []
    for attr in attrs:
        try:
            value = getattr(coin, attr, None)
        except Exception:
            value = None
        if value:
            parts.append(str(value))
    return " ".join(parts).lower()

def _keyword_matches(keyword, text):
    """Match whole words/phrases so e.g. 'fen' does not match 'pfennig'."""
    keyword = (keyword or "").strip().lower()
    if not keyword:
        return False
    pattern = r"(?<![a-z0-9])" + re.escape(keyword) + r"(?![a-z0-9])"
    return re.search(pattern, text) is not None

def _year_in_range(year, start, end):
    if year is None or start is None or end is None:
        return False
    lo, hi = sorted((start, end))
    return lo <= year <= hi

COUNTRY_ALIASES = {
    "united states": ("united states", "usa", "u.s.a", "us", "u.s."),
    "china": ("china", "people's republic of china", "prc"),
    "germany": ("germany", "german", "west germany", "east germany", "ddr"),
    "france": ("france", "french"),
    "japan": ("japan", "japanese"),
    "canada": ("canada", "canadian"),
    "russia": ("russia", "russian", "soviet union", "ussr"),
    "united kingdom": ("united kingdom", "great britain", "britain", "british", "england"),
    "ukraine": ("ukraine", "ukrainian"),
}

STRICT_EVENT_COUNTRIES = {
    "The People's Republic of China": ("china",),
    "The Civil Rights Act": ("united states",),
    "Apollo 11 Lands on the Moon": ("united states",),
    "September 11": ("united states",),
    "The Great Depression Begins": ("united states",),
    "The First Powered Flight": ("united states",),
    "The Model T": ("united states",),
    "The American Civil War Begins": ("united states",),
    "Emancipation": ("united states",),
}


def _country_matches(coin, required_countries):
    country_hay = _text(coin, attrs=["country"])
    for canonical in required_countries:
        aliases = COUNTRY_ALIASES.get(canonical, (canonical,))
        if any(_keyword_matches(alias, country_hay) for alias in aliases):
            return True
    return False


def _score_coin(coin, moment):
    year = _safe_int(getattr(coin, "year", None))
    hay = _text(coin)

    target_year = moment["target_year"]
    start = moment["start"]
    end = moment["end"]
    keywords = moment["keywords"]

    hits = sum(1 for keyword in keywords if _keyword_matches(keyword, hay))

    # For exact-year moments, the year alone is not enough.  Require the
    # historical clue to appear in identity/geography fields, not merely in
    # material or a generic denomination.  This prevents matches such as a
    # Belgian copper-nickel coin for a U.S. event just because "nickel" was
    # one of the U.S. denomination keywords.
    if target_year is not None:
        if year != target_year:
            return -1

        # Some moments are specifically tied to one nation. For those, a
        # same-year foreign coin is not a substitute.
        required_countries = STRICT_EVENT_COUNTRIES.get(moment["title"])
        if required_countries and not _country_matches(coin, required_countries):
            return -1

        identity_hay = _text(
            coin,
            attrs=["country", "name", "mint", "location", "ruler", "issuer", "region", "type"],
        )
        identity_hits = sum(
            1 for keyword in keywords
            if _keyword_matches(keyword, identity_hay)
        )

        if identity_hits == 0:
            return -1

        # Country matches are strongest, followed by other identity clues.
        country_hay = _text(coin, attrs=["country"])
        country_hits = sum(
            1 for keyword in keywords
            if _keyword_matches(keyword, country_hay)
        )
        return 40 + identity_hits * 8 + country_hits * 20

    # Ancient/medieval coins often cannot be assigned to one modern mint year.
    # These use a historically narrow range + a matching place/ruler/type clue.
    if not _year_in_range(year, start, end) or hits == 0:
        return -1

    score = 18 + hits * 8
    midpoint = (start + end) / 2
    span = max(1, abs(end - start) / 2)
    score += max(0, 5 - min(5, abs(year - midpoint) / span))
    return score

def build_human_story(coins):
    eras_out = []
    used_ids = set()
    total = 0
    completed = 0

    for era in ERAS:
        era_copy = dict(era)
        rows = []
        era_completed = 0

        for moment_tuple in era["moments"]:
            (
                title, dates, story, coin_rule,
                target_year, start, end, keywords, mode
            ) = moment_tuple

            moment = {
                "title": title,
                "dates": dates,
                "story": story,
                "coin_rule": coin_rule,
                "target_year": target_year,
                "start": start,
                "end": end,
                "keywords": keywords,
                "mode": mode,
            }

            total += 1
            ranked = []

            for coin in coins:
                cid = getattr(coin, "id", None)
                if cid in used_ids:
                    continue

                score = _score_coin(coin, moment)
                if score >= 0:
                    ranked.append((score, coin))

            ranked.sort(
                key=lambda item: (
                    item[0],
                    -(getattr(item[1], "id", 0) or 0),
                ),
                reverse=True,
            )

            matched = ranked[0][1] if ranked else None

            if matched is not None:
                cid = getattr(matched, "id", None)
                if cid is not None:
                    used_ids.add(cid)
                completed += 1
                era_completed += 1

            rows.append({
                "title": title,
                "dates": dates,
                "story": story,
                "coin_rule": coin_rule,
                "target_year": target_year,
                "coin": matched,
            })

        era_copy["moments"] = rows
        era_copy["completed"] = era_completed
        era_copy["total"] = len(rows)
        era_copy["percent"] = round((era_completed / len(rows) * 100) if rows else 0)
        eras_out.append(era_copy)

    percent = round((completed / total * 100) if total else 0)
    return eras_out, completed, total, percent
